const LEVELS=[
 {name:'BIDEN',subtitle:'THE ICE-CREAM SUMMIT',hint:'Dodge the scoops. Lecterns block movement, not bullets.',floor:'#252c3c',grid:'#303c50',accent:'#90c4ff',boss:'BIDEN / SCOOP COMMANDER',count:15,hp:105,roster:['chaser','shooter','charger','shield'],obstacles:[{x:260,y:225,w:60,h:95},{x:640,y:225,w:60,h:95}]},
 {name:'TRADE WAR',subtitle:'NOTHING TO DECLARE',hint:'Conveyors push everyone. Tax the crowd before it closes in.',floor:'#2c302a',grid:'#3b4439',accent:'#e7ca7b',boss:'THE TRADE DEFICIT',count:21,hp:155,roster:['charger','turret','shield','shooter','splitter','chaser'],belts:[{x:115,y:165,w:730,h:60,dir:1},{x:115,y:385,w:730,h:60,dir:-1}]},
 {name:'IRAN',subtitle:'THE ESCALATION MACHINE',hint:'Red circles explode after a warning. They hurt enemies too.',floor:'#362a32',grid:'#493640',accent:'#f3a47e',boss:'THE WAR MACHINE / MADE BY YOUR DECISIONS',count:24,hp:190,roster:['shooter','turret','charger','splitter','shield','chaser']}
];
const TYPES={chaser:{hp:3,r:16,speed:90,color:'#bbd66a'},charger:{hp:6,r:20,speed:48,color:'#ed946b'},shooter:{hp:4,r:17,speed:65,color:'#db96cc'},turret:{hp:5,r:19,speed:0,color:'#c8b0fa'},shield:{hp:7,r:21,speed:67,color:'#7fc8d0'},splitter:{hp:5,r:21,speed:72,color:'#efa8a1'},mini:{hp:1,r:10,speed:145,color:'#f4bdaf'}};
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let state='menu',wave=0,phase='mobs',score=0,player,enemies=[],bullets=[],shots=[],particles=[],hazards=[],spawned=0,total=0,spawnTimer=0,time=0,fire=0,shake=0,last=0,sound=false,audio,upgrades=[],kills=0,uid=0,field=null,hazardTimer=4,announcement='',announceTimer=0,stamp=0,touchMove=null,touchOrigin=null,miniFields=[],clones=[],effects=[],floaters=[],offeredItems=[],tutorialSeen=false,tutorialFinishTimer=0;
function tone(f=250,d=.07,type='square',v=.025){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,f/2),audio.currentTime+d);g.gain.setValueAtTime(v,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch(e){}}
function burst(x,y,color,n=12){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(30,220);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.6),color})}}
function show(html){overlay.innerHTML=html;overlay.classList.remove('hidden')}
function announce(text,d=3){announcement=text;announceTimer=d}
function reset(){player={x:480,y:400,r:14,hp:6,maxhp:6,speed:220,damage:1,rate:.19,multi:1,cd:0,jump:0,inv:0,tariffCd:0,dx:1,dy:0};wave=0;score=0;kills=0;time=0;upgrades=[];particles=[];offeredItems=[];effects=[];floaters=[];fire=0;shake=0;nextLevel();canvas.focus()}
function clearCombat(){enemies=[];bullets=[];shots=[];hazards=[];field=null;miniFields=[];clones=[];effects=[];floaters=[];spawned=0;stamp=0;touchMove=null;touchOrigin=null;mouse.down=false}
function nextLevel(){clearCombat();wave++;phase='mobs';spawnTimer=1;total=LEVELS[wave-1].count;hazardTimer=4;player.x=480;player.y=420;player.jump=0;player.cd=0;player.tariffCd=0;player.inv=2;state='play';overlay.classList.add('hidden');announce('CHAPTER '+wave+' / '+LEVELS[wave-1].name,3.5);hud()}
function spawn(type,position){const boss=type==='boss',cfg=boss?{hp:LEVELS[wave-1].hp,r:wave===1?32:43,speed:30,color:'#ad8bd9'}:TYPES[type];let edge=Math.floor(rand(0,4)),x=edge===0?48:edge===1?W-48:rand(60,W-60),y=edge===2?85:edge===3?H-45:rand(90,H-50);if(Math.hypot(x-player.x,y-player.y)<170){x=player.x<W/2?W-60:60;y=player.y<H/2?H-60:90}if(position){x=position.x;y=position.y}if(boss){x=480;y=145}const e={...cfg,id:uid++,x,y,type,maxhp:cfg.hp,t:rand(1,1.8),stun:0,flash:0,age:0,charge:0,vx:0,vy:0,tax:0,broken:0,face:Math.PI/2,bossPhase:0};enemies.push(e);return e}
function beginBoss(){phase='boss';bullets=[];shots=[];hazards=[];field=null;miniFields=[];clones=[];player.inv=2;spawn('boss');announce(LEVELS[wave-1].boss,3);tone(90,.3,'sawtooth')}
const choices=[
 {id:'pull',name:'扣押令',en:'Seizure Order',icon:'◎',desc:'关税区向中心拉怪。站位决定你能集中多少敌人。'},
 {id:'settle',name:'到期清算',en:'Final Settlement',icon:'◷',desc:'主关税结束时爆炸。区内命中越多，目标的清算伤害越高。'},
 {id:'bounce',name:'弹跳支票',en:'Bouncing Checks',icon:'↝',desc:'子弹可弹向另一只怪一次。被护盾挡住，也能转向附近目标。'},
 {id:'clone',name:'交叉火力',en:'Crossfire',icon:'♊',desc:'起跳点留下分身，朝你的瞄准点射击 3 秒。跳到另一侧夹击。'},
 {id:'landing',name:'落地签字',en:'Landing Clause',icon:'↓',desc:'落地留下 2 秒小关税区。带减益与吸引效果，但不会清算爆炸。'},
 {id:'chain',name:'违约连锁',en:'Default Cascade',icon:'✴',desc:'有关税减益的怪死亡时散射短程碎片。碎片击杀不会再次触发。'}
];
const SYNERGY={pull:{settle:'聚怪后持续命中，等待到期清算。',bounce:'把敌人聚到弹射距离内。',landing:'落地小关税也会吸引敌人。',chain:'聚集的敌人更容易被死亡碎片命中。'},settle:{bounce:'弹射可为更多区内目标累积清算。',clone:'分身命中也会累积清算伤害。'},bounce:{clone:'分身射出的子弹同样可以弹射。',chain:'弹射削弱群怪，帮助死亡碎片收尾。'},clone:{chain:'分身可击杀有减益的目标，启动碎片。'},landing:{chain:'落地小关税也能标记连锁目标。'}};
function has(id){return upgrades.includes(id)}
function itemById(id){return choices.find(u=>u.id===id)}
function synergy(a,b){return SYNERGY[a]?.[b]||SYNERGY[b]?.[a]||''}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(rand(0,i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function makeOffer(){const available=shuffle(choices.filter(u=>!has(u.id)));let offer=available.slice(0,3);if(upgrades.length&&!offer.some(u=>upgrades.some(id=>synergy(id,u.id)))){const match=available.find(u=>upgrades.some(id=>synergy(id,u.id)));if(match)offer[2]=match}return offer}
function upgrade(){state='upgrade';mouse.down=false;touchMove=null;offeredItems=makeOffer();show('<div class="tag">CHAPTER '+wave+' CLEARED · PICK A PLAYSTYLE</div><h2>Build a<br><em>better bad idea.</em></h2><p>恢复 2 颗心。选择一个机制道具。<br>Next: '+LEVELS[wave].name+'</p><div class="choices">'+offeredItems.map((u,i)=>{const partner=upgrades.find(id=>synergy(id,u.id));return '<button class="choice" data-choice="'+i+'"><span>'+u.icon+'</span><b>'+u.name+'</b><small class="itemen">'+u.en+'</small><small>'+u.desc+'</small>'+(partner?'<small class="synergy">联动 '+itemById(partner).name+'：'+synergy(partner,u.id)+'</small>':'')+'</button>'}).join('')+'</div>');overlay.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>chooseUpgrade(+b.dataset.choice))}
function chooseUpgrade(i){if(state!=='upgrade'||!offeredItems[i])return;upgrades.push(offeredItems[i].id);player.hp=Math.min(player.maxhp,player.hp+2);nextLevel()}
function getZones(){return field?[field,...miniFields]:miniFields}
function newZone(x,y,r,life,main=false){return{x,y,r,life,maxLife:life,main,hits:{}}}
function recordHit(e,s){if(s.kind==='shard')return;if(field&&distance(e,field)<field.r+e.r)field.hits[e.id]=(field.hits[e.id]||0)+1}
function damageEnemy(e,damage,source='bullet'){if(e.hp<=0)return;e.hp-=damage;e.flash=.12;if(e.hp<=0)e.noChainDeath=source==='shard'}
function settlement(z){if(!has('settle')||!z.main)return;effects.push({x:z.x,y:z.y,r:z.r,life:.6,max:.6,color:'#ffe091'});burst(z.x,z.y,'#ffe091',30);tone(130,.25,'triangle');for(const e of enemies)if(distance(z,e)<z.r+e.r){damageEnemy(e,2+Math.min(8,(z.hits[e.id]||0)*.5),'settlement');floatText(e.x,e.y-35,'清算 / SETTLED','#ffdf85')}}
function updateZones(dt){if(field){field.life-=dt;if(field.life<=0){const expired=field;field=null;settlement(expired)}}for(const z of miniFields)z.life-=dt;miniFields=miniFields.filter(z=>z.life>0)}
function floatText(x,y,text,color='#dcfb94'){floaters.push({x,y,text,color,life:1.25})}
function land(){if(has('landing'))miniFields.push(newZone(player.x,player.y,90,2));burst(player.x,player.y,'#dafb89',22);shake=5;effects.push({x:player.x,y:player.y,r:65,life:.5,max:.5,color:'#d9fb76'});let hit=false;for(const e of enemies)if(e.hp>0&&distance(e,player)<e.r+65){hit=true;if(getZones().some(z=>distance(e,z)<z.r+e.r))e.tax=1;e.stun=1.5;e.broken=3;damageEnemy(e,4,'landing');floatText(e.x,e.y-e.r-20,e.type==='shield'?'破盾 3秒 / SHIELD BROKEN':'眩晕 / STUNNED');}if(!hit)floatText(player.x,player.y-45,'落地冲击 / LANDING PULSE');return hit}
function emitShot(origin,target,kind='bullet'){const a=Math.atan2(target.y-origin.y,target.x-origin.x);shots.push({x:origin.x,y:origin.y-10,vx:Math.cos(a)*620,vy:Math.sin(a)*620,r:5,damage:1,life:1.8,kind,bounces:has('bounce')&&kind!=='shard'?1:0,visited:[]})}
function aimPoint(origin){if(touchMove)return enemies.filter(e=>e.hp>0).reduce((a,b)=>!a||distance(origin,b)<distance(origin,a)?b:a,null)||{x:origin.x+1,y:origin.y};return mouse}
function updateClones(dt){for(const c of clones){c.life-=dt;c.t-=dt;if(c.life>0&&c.t<=0){emitShot(c,aimPoint(c),'clone');c.t=.3}}clones=clones.filter(c=>c.life>0)}
function redirect(s,source){if(!s.bounces)return false;const target=enemies.filter(e=>e.hp>0&&e.id!==source.id&&!s.visited.includes(e.id)&&distance(source,e)<260).sort((a,b)=>distance(source,a)-distance(source,b))[0];if(!target)return false;s.bounces--;const a=Math.atan2(target.y-source.y,target.x-source.x);s.x=source.x+Math.cos(a)*(source.r+7);s.y=source.y+Math.sin(a)*(source.r+7);s.vx=Math.cos(a)*620;s.vy=Math.sin(a)*620;s.life=.65;s.ricochet=true;return true}
function updateShots(dt){for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;for(const e of enemies){if(e.hp>0&&s.life>0&&!s.visited.includes(e.id)&&distance(s,e)<e.r+s.r){s.visited.push(e.id);if(shieldBlocks(e,s)){burst(s.x,s.y,'#a7eff9',4);tone(700,.025,'sine',.01)}else{recordHit(e,s);damageEnemy(e,s.damage,s.kind);burst(s.x,s.y,'#ffee94',3)}if(!redirect(s,e))s.life=0;break}}}}
function fragments(e){for(let i=0;i<8;i++){const a=i*Math.PI/4;shots.push({x:e.x+Math.cos(a)*(e.r+6),y:e.y+Math.sin(a)*(e.r+6),vx:Math.cos(a)*380,vy:Math.sin(a)*380,r:5,damage:2,life:.5,kind:'shard',bounces:0,visited:[e.id]})}floatText(e.x,e.y-35,'违约连锁 / CASCADE','#ffb9c8')}
function startRun(){if(tutorialSeen){reset();return}showTutorial()}
function showTutorial(){reset();state='tutorialIntro';show('<div class="tag">15-SECOND JUMP LESSON · 可跳过</div><h2>跳跃，<em>也是攻击。</em></h2><p><b>SPACE / JUMP</b>：跳跃期间免伤。<br>落地冲击圈：4 点伤害 ＋ 1.5 秒眩晕。<br><b>护盾怪被震到，会破盾 3 秒。</b><br>接下来用不会攻击的练习怪试一次。</p><button class="primary" id="practice">练习落地破盾 ↗</button><button class="small tutorials" id="skiplesson">跳过，开始游戏</button>');document.getElementById('practice').onclick=beginTutorial;document.getElementById('skiplesson').onclick=()=>{tutorialSeen=true;reset()}}
function beginTutorial(){clearCombat();state='tutorial';phase='tutorial';player.x=480;player.y=420;player.inv=999;player.jump=0;player.cd=0;const dummy=spawn('shield',{x:480,y:370});dummy.training=true;announceTimer=0;overlay.classList.add('hidden');canvas.focus()}
function finishTutorial(){tutorialSeen=true;state='tutorialDone';mouse.down=false;touchMove=null;show('<div class="tag">SHIELD BROKEN ✓</div><h2>破盾之后，<em>再开火。</em></h2><p>刚才的落地让护盾失效 3 秒。<br>实战中：跳近护盾怪 → 落地眩晕、破盾 → 射击。<br>别忘了：Q 关税减速，可以帮你接近落点。</p><button class="primary" id="lessonDone">明白了，开始第一关 ↗</button>');document.getElementById('lessonDone').onclick=reset}
function updateTutorial(dt){player.cd=Math.max(0,player.cd-dt);const was=player.jump>0;player.jump=Math.max(0,player.jump-dt);let mx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),my=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(touchMove){mx=touchMove.x;my=touchMove.y}const n=Math.max(1,Math.hypot(mx,my));player.x+=mx/n*220*dt*(player.jump>0?1.65:1);player.y+=my/n*220*dt*(player.jump>0?1.65:1);resolveBody(player);if(was&&player.jump===0&&land()){tutorialSeen=true;tutorialFinishTimer=1.1;state='tutorialSuccess'}hud()}
function updateTutorialSuccess(dt){tutorialFinishTimer-=dt;if(tutorialFinishTimer<=0)finishTutorial()}
function end(win){state=win?'win':'dead';mouse.down=false;touchMove=null;hud();tone(win?650:100,.5,'sawtooth');show('<div class="tag">'+(win?'THREE CAMPAIGNS. ONE VERY STRANGE VICTORY.':'CAMPAIGN ENDED')+'</div><h2>'+(win?'Victory.<br><em>At what cost?</em>':'The campaign<br><em>got you.</em>')+'</h2><p>'+(win?'The war machine is down. The consequences remain.':'Try a different build. Use tariffs to create breathing room.')+'<br>Score '+score+' · '+kills+' enemies · '+Math.floor(time)+' seconds</p><button class="primary" id="again">RUN IT BACK ↗</button>');document.getElementById('again').onclick=reset}
function hud(){document.getElementById('health').textContent='♥ '.repeat(player?player.hp:6)+'♡ '.repeat(player?player.maxhp-player.hp:0);document.getElementById('score').textContent=String(score).padStart(4,'0');document.getElementById('wave').textContent=(wave||'—')+' / 3';document.getElementById('jumptext').textContent=player&&player.cd>0?player.cd.toFixed(1)+'s':'READY';document.getElementById('jumpmeter').style.width=(player?(1-player.cd/1.5)*100:100)+'%';document.getElementById('tarifftext').textContent=field?'ACTIVE '+field.life.toFixed(1)+'s':player&&player.tariffCd>0?player.tariffCd.toFixed(1)+'s':'READY';document.getElementById('tariffmeter').style.width=(player?(1-player.tariffCd/12)*100:100)+'%';document.getElementById('build').innerHTML='<b>✦ Golden Blaster</b><br>＋ Q: Tariff zone<br>'+ (upgrades.length?upgrades.map(id=>'<b>'+itemById(id).icon+' '+itemById(id).name+'</b><div class="builddesc">'+itemById(id).desc+'</div>').join('')+(upgrades.length===2&&synergy(upgrades[0],upgrades[1])?'<div class="buildsynergy">联动：'+synergy(upgrades[0],upgrades[1])+'</div>':''):'<span style="font-size:10px">Defeat bosses to choose upgrades.</span>')}
function jump(){if(!['play','tutorial'].includes(state)||player.cd>0)return;if(state==='play'&&has('clone'))clones.push({x:player.x,y:player.y,life:3,t:0});player.jump=.58;player.cd=1.5;tone(390,.16,'sine');burst(player.x,player.y,'#d9fb76',8)}
function tariff(){if(state!=='play'||player.tariffCd>0)return;field=newZone(player.x,player.y,170,5,true);player.tariffCd=12;burst(player.x,player.y,'#ffe087',30);tone(600,.23,'triangle');hud()}
function hurt(){if(player.inv>0||player.jump>0||state!=='play')return;player.hp--;player.inv=1.3;shake=12;burst(player.x,player.y,'#ff855c',20);tone(110,.15,'sawtooth');if(player.hp<=0)end(false)}
function inRect(p,b){return p.x>b.x&&p.x<b.x+b.w&&p.y>b.y&&p.y<b.y+b.h}
function resolveBody(p){p.x=clamp(p.x,28+p.r,W-28-p.r);p.y=clamp(p.y,75+p.r,H-28-p.r);for(const b of LEVELS[wave-1].obstacles||[]){const x=clamp(p.x,b.x,b.x+b.w),y=clamp(p.y,b.y,b.y+b.h);let dx=p.x-x,dy=p.y-y,d=Math.hypot(dx,dy);if(d<p.r){if(d>0){p.x=x+dx/d*p.r;p.y=y+dy/d*p.r}else{const sides=[{d:p.x-b.x,x:b.x-p.r,y:p.y},{d:b.x+b.w-p.x,x:b.x+b.w+p.r,y:p.y},{d:p.y-b.y,x:p.x,y:b.y-p.r},{d:b.y+b.h-p.y,x:p.x,y:b.y+b.h+p.r}].sort((a,b)=>a.d-b.d);p.x=sides[0].x;p.y=sides[0].y}}}}
function conveyor(p,dt){if(p===player&&player.jump>0)return;for(const b of LEVELS[wave-1].belts||[])if(inRect(p,b))p.x+=b.dir*95*dt}
function enemyBullet(x,y,a,s=180,r=5,homing=false){bullets.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,r,life:7,homing})}
function warning(x,y,r=65,delay=1.45){hazards.push({x:clamp(x,50,W-50),y:clamp(y,90,H-50),r,t:delay,max:delay,blast:0,done:false})}
function updateHazards(dt){for(const h of hazards){h.t-=dt;if(h.t<=0&&!h.done){h.done=true;h.blast=.42;burst(h.x,h.y,'#ffa468',28);shake=10;tone(65,.2,'sawtooth');if(distance(h,player)<h.r+player.r)hurt();for(const e of enemies)if(distance(h,e)<h.r+e.r){damageEnemy(e,e.type==='boss'?5:9,'hazard');e.flash=.2}}if(h.done)h.blast-=dt}hazards=hazards.filter(h=>!h.done||h.blast>0)}
function fireBoss(e,a){if(wave===1){for(let i=-2;i<=2;i++)enemyBullet(e.x,e.y,a+i*.28,135,8);enemyBullet(e.x,e.y,a,105,11,true);e.t=e.hp<e.maxhp*.5?1.0:1.5}else if(wave===2){for(let i=0;i<12;i++)enemyBullet(e.x,e.y,i*Math.PI/6+e.age*.42,150,6);for(let i=-1;i<=1;i++)enemyBullet(e.x,e.y,a+i*.12,230);e.t=e.hp<e.maxhp*.5?.9:1.3}else{const n=e.hp<e.maxhp*.5?14:10;for(let i=0;i<n;i++)enemyBullet(e.x,e.y,i*2*Math.PI/n+e.age*.5,155);warning(player.x,player.y,60,1.45);e.t=e.hp<e.maxhp*.5?1:1.5}}
function updateEnemies(dt){for(const e of enemies){if(e.hp<=0)continue;e.age+=dt;e.flash=Math.max(0,e.flash-dt);e.stun=Math.max(0,e.stun-dt);e.broken=Math.max(0,e.broken-dt);const zone=getZones().filter(z=>distance(e,z)<z.r+e.r).sort((a,b)=>distance(e,a)-distance(e,b))[0],inside=!!zone;if(zone&&has('pull')){const d=distance(e,zone),step=Math.min(d,(e.type==='boss'?40:80)*dt);if(d>0){e.x+=(zone.x-e.x)/d*step;e.y+=(zone.y-e.y)/d*step}}e.tax=inside?1:Math.max(0,e.tax-dt);const taxed=e.tax>0,boss=e.type==='boss',speedScale=taxed?(boss?.8:.6):1,attackScale=taxed&&!boss?1/1.3:1;e.t-=dt*attackScale;if(e.stun>0)continue;const a=Math.atan2(player.y-e.y,player.x-e.x);e.face=a;
if(boss){const p=e.hp<e.maxhp*.35?2:e.hp<e.maxhp*.68?1:0;if(p>e.bossPhase){e.bossPhase=p;if(wave===3){stamp=3;announce('MISSION ACCOMPLISHED… AGAIN.',3);for(let i=0;i<3+p;i++)warning(rand(90,870),rand(130,520),70,2.2)}}e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt;if(e.t<=0)fireBoss(e,a)}
else if(e.type==='charger'){if(e.charge>0){e.charge-=dt;e.x+=e.vx*speedScale*dt;e.y+=e.vy*speedScale*dt}else if(e.t<=0){e.charge=.45;e.vx=Math.cos(a)*420;e.vy=Math.sin(a)*420;e.t=2.1}else{e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt}}
else if(e.type==='turret'){if(e.t<=0){for(let i=-2;i<=2;i++)enemyBullet(e.x,e.y,a+i*.23,165);e.t=2.1}}
else if(e.type==='shooter'){if(distance(player,e)>245){e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt}if(e.t<=0){enemyBullet(e.x,e.y,a,185);e.t=1.65}}
else{e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt}conveyor(e,dt);resolveBody(e);if(distance(e,player)<e.r+player.r)hurt()}}
function shieldBlocks(e,s){return e.type==='shield'&&e.broken<=0&&e.stun<=0&&Math.cos(Math.atan2(s.y-e.y,s.x-e.x)-e.face)>.25}
function reap(){const dead=enemies.filter(e=>e.hp<=0);enemies=enemies.filter(e=>e.hp>0);for(const e of dead){score+=e.type==='boss'?1000:e.type==='mini'?15:50;kills++;burst(e.x,e.y,e.color,22);tone(220,.08,'triangle');shake=Math.max(shake,3);if(has('chain')&&e.tax>0&&!e.noChainDeath)fragments(e);if(e.type==='splitter')for(const dir of [-1,1])spawn('mini',{x:clamp(e.x+dir*17,45,915),y:e.y})}}
function update(dt){time+=dt;announceTimer=Math.max(0,announceTimer-dt);stamp=Math.max(0,stamp-dt);player.inv=Math.max(0,player.inv-dt);player.cd=Math.max(0,player.cd-dt);player.tariffCd=Math.max(0,player.tariffCd-dt);updateZones(dt);const wasJumping=player.jump>0;player.jump=Math.max(0,player.jump-dt);if(wasJumping&&player.jump===0)land();
let mx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),my=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(touchMove){mx=touchMove.x;my=touchMove.y}const norm=Math.hypot(mx,my);if(norm){mx/=Math.max(1,norm);my/=Math.max(1,norm);player.dx=mx;player.dy=my}const speed=player.speed*dt*(player.jump>0?1.65:1);player.x+=mx*speed;player.y+=my*speed;conveyor(player,dt);resolveBody(player);
fire-=dt;if((mouse.down||touchMove)&&fire<=0){fire=player.rate;emitShot(player,aimPoint(player));tone(460,.04,'triangle',.02)}
spawnTimer-=dt;if(phase==='mobs'&&spawned<total&&spawnTimer<=0){spawnTimer=Math.max(.55,1.15-wave*.12);const roster=LEVELS[wave-1].roster;spawn(roster[spawned%roster.length]);spawned++}if(wave===3){hazardTimer-=dt;if(hazardTimer<=0){hazardTimer=phase==='boss'?3.8:4.5;warning(player.x+rand(-55,55),player.y+rand(-55,55),65);if(phase==='boss')warning(rand(80,880),rand(120,520),65)}}
updateEnemies(dt);updateClones(dt);updateShots(dt);
for(const b of bullets){if(b.homing){const speed=Math.hypot(b.vx,b.vy),a=Math.atan2(player.y-b.y,player.x-b.x),blend=dt*.7;b.vx=b.vx*(1-blend)+Math.cos(a)*speed*blend;b.vy=b.vy*(1-blend)+Math.sin(a)*speed*blend}b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(distance(b,player)<b.r+player.r&&player.jump<=0){hurt();b.life=0}}
updateHazards(dt);reap();shots=shots.filter(s=>s.life>0&&s.x>0&&s.x<W&&s.y>0&&s.y<H);bullets=bullets.filter(s=>s.life>0&&s.x>0&&s.x<W&&s.y>0&&s.y<H);if(state==='play'&&spawned>=total&&enemies.length===0){if(phase==='mobs')beginBoss();else if(wave===3)end(true);else upgrade()}hud()}
